{"code": "import PIL
from PIL import Image

# Try to open each image to see if any are corrupt
all_jpgs = list(pathlib.Path('data/web_scraped_small').glob('*/*.jpg'))
print("Testing all images with PIL:")
for i, img_path in enumerate(all_jpgs):
    try:
        img = Image.open(str(img_path))
        img.verify()
    except Exception as e:
        print(f"ERROR in {img_path}: {type(e).__name__}: {e}")"}

